function longestKRepeatStretch(s: string, k: number): number {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    const cnt = new Array(26).fill(0);
    let below = 0; // letters present but still under k
    for (let j = i; j < s.length; j++) {
      const c = s.charCodeAt(j) - 97;
      cnt[c]++;
      if (cnt[c] === 1 && k > 1) below++;
      if (cnt[c] === k && k > 1) below--;
      if (below === 0) best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

