function longestKRepeatStretch(s: string, k: number): number {
  const solve = (lo: number, hi: number): number => {
    if (hi - lo < k) return 0;
    const cnt = new Array(26).fill(0);
    for (let i = lo; i < hi; i++) cnt[s.charCodeAt(i) - 97]++;
    let best = 0, start = lo, split = false;
    for (let i = lo; i <= hi; i++) {
      if (i === hi || cnt[s.charCodeAt(i) - 97] < k) {
        if (i === hi && !split) return hi - lo; // no walls: the whole range is valid
        split = true;
        best = Math.max(best, solve(start, i));
        start = i + 1;
      }
    }
    return best;
  };
  return solve(0, s.length);
}

