class Solution:
    def longestKRepeatStretch(self, s: str, k: int) -> int:
        def solve(lo: int, hi: int) -> int:
            if hi - lo < k:
                return 0
            cnt = Counter(s[lo:hi])
            walls = [i for i in range(lo, hi) if cnt[s[i]] < k]
            if not walls:
                return hi - lo
            best, start = 0, lo
            for w in walls + [hi]:
                best = max(best, solve(start, w))
                start = w + 1
            return best

        return solve(0, len(s))

