function longestKRepeatStretch(s: string, k: number): number {
  let best = 0;
  for (let u = 1; u <= 26; u++) {
    const cnt = new Array(26).fill(0);
    let lo = 0, distinct = 0, atK = 0;
    for (let hi = 0; hi < s.length; hi++) {
      const c = s.charCodeAt(hi) - 97;
      if (cnt[c]++ === 0) distinct++;
      if (cnt[c] === k) atK++;
      while (distinct > u) {
        const d = s.charCodeAt(lo++) - 97;
        if (cnt[d]-- === k) atK--;
        if (cnt[d] === 0) distinct--;
      }
      if (distinct === u && atK === u) best = Math.max(best, hi - lo + 1);
    }
  }
  return best;
}

